import java.util.*;
public class CF375B {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        String inputStr = scanner.next().toLowerCase();
        String originalStr = inputStr;
        char[] chars = inputStr.toCharArray();
        StringBuilder sb = new StringBuilder(originalStr);
        Stack<Character> stack = new Stack<>();
        for (char c : chars) {
            stack.push(c);
        }
        List<Integer> bracketsPositions = new ArrayList<>();
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] == '(' || chars[i] == ')') {
                stack.pop();
                bracketsPositions.add(i);
            }
        }
        TreeMap<Integer, Integer> bracketPairs = new TreeMap<>();
        for (int i = 0; i < bracketsPositions.size(); i += 2) {
            bracketPairs.put(bracketsPositions.get(i), bracketsPositions.get(i + 1));
        }
        List<Integer> indicesToRemove = new ArrayList<>();
        for (Map.Entry<Integer, Integer> entry : bracketPairs.entrySet()) {
            int start = entry.getKey();
            int end = entry.getValue();
            for (int i = start; i <= end; i++) {
                indicesToRemove.add(i);
            }
        }
        List<Integer> removeSet = new ArrayList<>(indicesToRemove);
        char[] filteredChars = new char[chars.length - removeSet.size()];
        char[] replacedChars = new char[filteredChars.length];
        int idxFiltered = 0, idxReplaced = 0;
        for (int i = 0; i < chars.length; i++) {
            if (!removeSet.contains(i)) {
                filteredChars[idxFiltered++] = chars[i];
            }
        }
        boolean toggle = true;
        for (int i = 0; i < chars.length; i++) {
            if (removeSet.contains(i)) {
                if (chars[i] == '(' || chars[i] == ')' || chars[i] == '_') {
                    if (toggle) {
                        replacedChars[idxReplaced++] = ' ';
                        toggle = false;
                    }
                } else {
                    replacedChars[idxReplaced++] = chars[i];
                    toggle = true;
                }
            }
        }
        StringBuilder resultBuilder = new StringBuilder();
        for (char c : replacedChars) {
            resultBuilder.append(c);
        }
        String[] splitParts = resultBuilder.toString().split(" ");
        List<Integer> lengthsAfter = new ArrayList<>();
        for (String part : splitParts) {
            String trimmed = part.trim();
            if (trimmed.length() != 0) {
                lengthsAfter.add(trimmed.length());
            }
        }
        List<Integer> lengthsBefore = new ArrayList<>();
        String replacedStr = inputStr.replaceAll("\\(.*?\\) ?", " ").replace("_", " ");
        String[] originalParts = replacedStr.split(" ");
        for (String part : originalParts) {
            String trimmed = part.trim();
            if (trimmed.length() != 0) {
                lengthsBefore.add(trimmed.length());
            }
        }
        Collections.sort(lengthsAfter);
        int maxLength = lengthsAfter.size() == 0 ? 0 : lengthsAfter.get(lengthsAfter.size() - 1);
        System.out.print(maxLength + " " + lengthsBefore.size());
    }
}
